/** SPA 静的配信（gzip アセットをインライン化） */
import type { Context } from 'hono';
import type { AppEnv } from './types.ts';

// ビルド時に scripts/embed-spa.mjs が生成・置換する
/** 自動生成: SPAアセット（scripts/embed-spa.mjs） */
export const SPA_ASSETS: Record<string, { b64: string; ct: string }> = {"index.html":{"b64":"","ct":"text/html; charset=utf-8"},"assets/index-B7g2K3SL.css":{"b64":"","ct":"text/css; charset=utf-8"},"assets/index-CF0JBMwl.js":{"b64":"","ct":"application/javascript; charset=utf-8"}};


const CONTENT_TYPE_FALLBACK = 'application/octet-stream';

async function decodeGzip(b64: string): Promise<Response> {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const ds = new DecompressionStream('gzip');
  const stream = new Blob([bytes]).stream().pipeThrough(ds);
  return new Response(stream);
}

/** SPA 静的配信（GET のみ・API以外のパス） */
export async function staticAssets(c: Context<AppEnv>, next: () => Promise<unknown>) {
  const method = c.req.method;
  if (method !== 'GET' && method !== 'HEAD') return next();
  const url = new URL(c.req.url);
  const path = url.pathname;
  if (path.startsWith('/api/')) return next();

  const key = path.replace(/^\//, '') || 'index.html';
  const asset = SPA_ASSETS[key];
  if (!asset) {
    // SPAフォールバック（クライアントルーティング）
    if (!path.includes('.') && SPA_ASSETS['index.html']) {
      const resp = await decodeGzip(SPA_ASSETS['index.html'].b64);
      return new Response(resp.body, { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
    }
    return next();
  }
  const resp = await decodeGzip(asset.b64);
  const headers: Record<string, string> = {
    'Content-Type': asset.ct || CONTENT_TYPE_FALLBACK,
    // index.html は毎回再検証、ハッシュ付きアセットは内容不変のため長期キャッシュ
    'Cache-Control': key.includes('index.html') ? 'no-store' : 'public, max-age=31536000, immutable',
  };
  return new Response(resp.body, { status: 200, headers });
}
